def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Report_Categories.csv'
    # try encodings
    last_err = None
    for enc in ['utf-8-sig','cp1252','latin1']:
        try:
            raw = pd.read_csv(path, encoding=enc, header=None)
            used = enc
            break
        except Exception as e:
            last_err = e
    else:
        raise last_err

    # find header row containing 'Rank' and 'Category'
    header_idx = None
    for i in range(min(50, len(raw))):
        row = raw.iloc[i].astype(str).str.strip().str.lower().tolist()
        if any('rank' == x for x in row) and any('category' == x for x in row):
            header_idx = i
            break
    if header_idx is None:
        # fallback: first row
        header_idx = 0

    df = pd.read_csv(path, encoding=used, header=header_idx)
    df.columns = [str(c).strip() for c in df.columns]

    # drop fully empty rows
    df = df.dropna(how='all')

    # keep relevant columns if present
    # Normalize column names
    colmap = {}
    for c in df.columns:
        cl = c.lower().strip()
        if cl == 'rank':
            colmap[c] = 'Rank'
        elif cl == 'category':
            colmap[c] = 'Category'
        elif 'reports' in cl:
            colmap[c] = 'Reports'
        elif 'percentage' in cl or cl.startswith('%'):
            colmap[c] = 'Percentage'
    df = df.rename(columns=colmap)

    # parse reports and percentage
    if 'Reports' in df.columns:
        df['Reports'] = df['Reports'].astype(str).str.replace(',', '', regex=False).str.replace('\u00a0','', regex=False).str.strip()
        df['Reports'] = pd.to_numeric(df['Reports'], errors='coerce')
    if 'Percentage' in df.columns:
        df['Percentage'] = df['Percentage'].astype(str).str.replace('%','', regex=False).str.strip()
        df['Percentage'] = pd.to_numeric(df['Percentage'], errors='coerce')

    df['__encoding_used'] = used
    return df

def process(categories) -> pd.DataFrame:
    import pandas as pd
    df = categories.copy()
    df = df[df['Category'].notna()]
    row = df[df['Category'].str.strip().str.lower()=='imposter scams']
    if row.empty:
        return pd.DataFrame([{'group':'general','imposter_reports':None,'total_reports':None,'imposter_pct':None}])
    imposter_reports = float(row['Reports'].iloc[0])
    # total reports given in note: 6,471,708
    total_reports = 6471708.0
    imposter_pct = imposter_reports/total_reports*100
    return pd.DataFrame([{'group':'general','imposter_reports':imposter_reports,'total_reports':total_reports,'imposter_pct':imposter_pct,'pct_from_table':float(row['Percentage'].iloc[0])}])

def process(general_imposter_pct, military_imposter_pct):
    import pandas as pd
    g = float(general_imposter_pct['imposter_pct'].iloc[0])
    m = float(military_imposter_pct['imposter_pct'].iloc[0])
    return pd.DataFrame([{
        'general_imposter_pct': g,
        'military_imposter_pct': m,
        'military_higher': 'Yes' if m > g else 'No'
    }])
